[
  {
    "version": "v1.0",
    "createSurface": {
      "surfaceId": "main",
      "catalogId": "https://a2ui.org/samples/community/agent/adk/mcp_app_proxy/catalogs/0.9/mcp_app_catalog.json",
      "components": [
        {
          "id": "scoreBoard",
          "component": "PongScoreBoard",
          "playerScore": {
            "path": "/pong/playerScore"
          },
          "cpuScore": {
            "path": "/pong/cpuScore"
          },
          "commentary": {
            "path": "/pong/commentary"
          }
        },
        {
          "id": "mcpComp",
          "component": "McpApp",
          "htmlContent": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Neon Pong</title>
<style>
  body, html {
    margin: 0; padding: 0; overflow: hidden; background: #0a0a16;
    width: 100%; height: 100%; display: flex; justify-content: center; align-items: center;
    font-family: 'Courier New', Courier, monospace;
    user-select: none;
    -webkit-user-select: none;
  }
  canvas {
    background: #0d0d26;
    border: 4px solid #00f0ff;
    box-shadow: 0 0 20px #00f0ff, inset 0 0 20px #00f0ff;
    display: block;
    max-width: 95vw;
    max-height: 90vh;
    border-radius: 8px;
  }
</style>
</head>
<body>
<canvas id="pongCanvas" width="800" height="500"></canvas>
<script>
  const canvas = document.getElementById('pongCanvas');
  const ctx = canvas.getContext('2d');

  let audioCtx = null;
  function initAudio() {
    if (!audioCtx) {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
  }

  function beep(freq, duration) {
    if (!audioCtx) return;
    try {
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.frequency.value = freq;
      osc.type = 'square';
      gain.gain.setValueAtTime(0.04, audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
      osc.start(audioCtx.currentTime);
      osc.stop(audioCtx.currentTime + duration);
    } catch(e) {}
  }

  const ball = { x: canvas.width / 2, y: canvas.height / 2, radius: 8, speed: 7, dx: 7, dy: 7, color: '#ff007f' };
  const player = { x: 20, y: canvas.height / 2 - 50, width: 12, height: 100, score: 0, color: '#39ff14' };
  const cpu = { x: canvas.width - 32, y: canvas.height / 2 - 50, width: 12, height: 100, score: 0, color: '#00e5ff' };

  let keys = {};
  window.addEventListener('keydown', e => {
    initAudio();
    keys[e.key] = true;
  });
  window.addEventListener('keyup', e => keys[e.key] = false);

  canvas.addEventListener('mousemove', e => {
    initAudio();
    const rect = canvas.getBoundingClientRect();
    player.y = (e.clientY - rect.top) * (canvas.height / rect.height) - player.height / 2;
  });

  canvas.addEventListener('touchmove', e => {
    initAudio();
    const rect = canvas.getBoundingClientRect();
    const touch = e.touches[0];
    player.y = (touch.clientY - rect.top) * (canvas.height / rect.height) - player.height / 2;
    e.preventDefault();
  }, { passive: false });

  function drawRect(x, y, w, h, color) {
    ctx.fillStyle = color;
    ctx.shadowBlur = 15;
    ctx.shadowColor = color;
    ctx.fillRect(x, y, w, h);
    ctx.shadowBlur = 0;
  }

  function drawCircle(x, y, r, color) {
    ctx.fillStyle = color;
    ctx.shadowBlur = 15;
    ctx.shadowColor = color;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2, false);
    ctx.closePath();
    ctx.fill();
    ctx.shadowBlur = 0;
  }

  function drawNet() {
    ctx.strokeStyle = 'rgba(0, 240, 255, 0.15)';
    ctx.setLineDash([15, 15]);
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(canvas.width / 2, 0);
    ctx.lineTo(canvas.width / 2, canvas.height);
    ctx.stroke();
  }

  function resetBall() {
    ball.x = canvas.width / 2;
    ball.y = canvas.height / 2;
    ball.speed = 7;
    ball.dx = -ball.dx;
  }

  function update() {
    if (keys['ArrowUp'] || keys['w']) player.y -= 8;
    if (keys['ArrowDown'] || keys['s']) player.y += 8;
    player.y = Math.max(0, Math.min(canvas.height - player.height, player.y));

    let targetY = ball.y - cpu.height / 2;
    let diff = targetY - cpu.y;
    let cpuSpeed = 6.2;
    if (Math.abs(diff) > 10) {
      cpu.y += Math.sign(diff) * cpuSpeed;
    }
    cpu.y = Math.max(0, Math.min(canvas.height - cpu.height, cpu.y));

    ball.x += ball.dx;
    ball.y += ball.dy;

    if (ball.y + ball.radius > canvas.height) {
      ball.y = canvas.height - ball.radius;
      ball.dy = -ball.dy;
      beep(300, 0.08);
    } else if (ball.y - ball.radius < 0) {
      ball.y = ball.radius;
      ball.dy = -ball.dy;
      beep(300, 0.08);
    }

    let paddle = (ball.x < canvas.width / 2) ? player : cpu;

    if (collision(ball, paddle)) {
      let collidePoint = (ball.y - (paddle.y + paddle.height/2));
      collidePoint = collidePoint / (paddle.height/2);
      let angleRad = (Math.PI/3) * collidePoint;
      let direction = (ball.x < canvas.width/2) ? 1 : -1;
      ball.dx = direction * ball.speed * Math.cos(angleRad);
      ball.dy = ball.speed * Math.sin(angleRad);
      ball.speed += 0.4;
      beep(600, 0.1);
    }

    if (ball.x - ball.radius < 0) {
      cpu.score++;
      beep(150, 0.35);
      updateScores("CPU scores with an incredible angle shot!");
      resetBall();
    } else if (ball.x + ball.radius > canvas.width) {
      player.score++;
      beep(880, 0.35);
      updateScores("Incredible return! You scored!");
      resetBall();
    }
  }

  function collision(b, p) {
    return b.x + b.radius > p.x && b.x - b.radius < p.x + p.width &&
           b.y + b.radius > p.y && b.y - b.radius < p.y + p.height;
  }

  function updateScores(comment) {
    if (window.parent) {
      const data = {
        playerScore: player.score,
        cpuScore: cpu.score,
        commentary: comment || "Keep playing!"
      };
      window.parent.postMessage({ type: 'update', data: data }, '*');
      window.parent.postMessage({ type: 'a2ui:update', data: data }, '*');
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawNet();
    drawRect(player.x, player.y, player.width, player.height, player.color);
    drawRect(cpu.x, cpu.y, cpu.width, cpu.height, cpu.color);
    drawCircle(ball.x, ball.y, ball.radius, ball.color);
  }

  function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
  }
  loop();
</script>
</body>
</html>",
          "title": "Neon Pong",
          "data": {
            "path": "/pong"
          }
        },
        {
          "id": "root",
