          "scoreboardComponent": "scoreBoard"
        }
      ],
      "dataModel": {
        "pong": {
          "playerScore": 0,
          "cpuScore": 0,
          "commentary": "Control your neon paddle with Mouse, Touch, or Keyboard (W/S or Arrow Keys)!"
        }
      }
    }
  }
]

